BEGIN TRANSACTION;
CREATE TABLE "Customers" (
"customer_id" TEXT,
  "customer_name" TEXT,
  "gender" TEXT,
  "age" REAL,
  "city" TEXT,
  "region" TEXT,
  "signup_date" TIMESTAMP,
  "customer_segment" TEXT,
  "age_filled" INTEGER
);
CREATE TABLE "Inventory" (
"inventory_id" TEXT,
  "warehouse_id" TEXT,
  "product_id" TEXT,
  "stock_on_hand" REAL,
  "reorder_level" INTEGER,
  "snapshot_date" TIMESTAMP,
  "stock_filled" INTEGER
);
CREATE TABLE "Order_Items" (
"order_item_id" TEXT,
  "order_id" TEXT,
  "product_id" TEXT,
  "quantity" REAL,
  "unit_price" REAL,
  "discount_pct" REAL,
  "line_revenue" REAL,
  "line_cost" REAL,
  "quantity_filled" INTEGER,
  "discount_filled" INTEGER,
  "product_id_filled" INTEGER
);
CREATE TABLE "Orders" (
"order_id" TEXT,
  "customer_id" TEXT,
  "order_date" TIMESTAMP,
  "sales_channel" TEXT,
  "order_status" TEXT,
  "payment_method" TEXT,
  "campaign" TEXT,
  "warehouse_id" TEXT,
  "delivery_days" REAL,
  "delivery_days_filled" INTEGER
);
CREATE TABLE "Products" (
"product_id" TEXT,
  "product_name" TEXT,
  "category" TEXT,
  "unit_cost" REAL,
  "unit_price" REAL,
  "supplier_id" TEXT,
  "active" INTEGER
);
CREATE TABLE "Reviews" (
"review_id" TEXT,
  "order_id" TEXT,
  "review_date" TIMESTAMP,
  "rating" REAL,
  "review_text" TEXT,
  "sentiment_label" TEXT,
  "rating_filled" INTEGER,
  "review_date_invalid" INTEGER
);
CREATE TABLE "Suppliers" (
"supplier_id" TEXT,
  "supplier_name" TEXT,
  "supplier_country" TEXT,
  "lead_time_days" INTEGER,
  "supplier_rating" REAL
);
CREATE TABLE "Warehouses" (
"warehouse_id" TEXT,
  "warehouse_name" TEXT,
  "region" TEXT
);
COMMIT;
